    fun getLessonById(id: String): StudyLesson? {
        return defaultStudyGuide.lessons.find { it.id == id }
    }

    fun getLessonsByLevel(level: Int): List<StudyLesson> {
        return defaultStudyGuide.lessons.filter { it.level == level }
    }
